                for cid in re.findall(r'::(?:error|warning)::(\w+) failed', out): ci_fail[cid] += 1
                if n == 'ReadNotifications':
                    for cid in re.findall(r'"name":\s*"([\w -]+)"[^}]*"conclusion":\s*"failure"', out): ci_fail['CI job: ' + cid] += 1
    per_sess[sid] = (ps, pst)

